import { SchematicsException, Tree } from '@angular-devkit/schematics';
import { readText } from './text';

/** Paths of a project generated by `nest-schematics new`. */
export interface NestProject {
  root: string;
  apiSrc: string;
  apiModule: string;
  apiMain: string;
  commonSrc: string;
  databaseSrc: string;
  entitiesDir: string;
  /** Apps listed in nest-cli.json. */
  apps: string[];
}

/**
 * Locates the project in the current directory. Every add-on calls this
 * first, so running one outside a project fails with a clear message.
 */
export function getProject(tree: Tree, root = ''): NestProject {
  const prefix = root ? `${root}/` : '';
  const cliPath = `${prefix}nest-cli.json`;
  if (!tree.exists(cliPath) || !tree.exists(`${prefix}libs/database/src/base.entity.ts`)) {
    throw new SchematicsException(
      'Run this inside a project created with "npx nest-schematics new <name>" (nest-cli.json and libs/database not found).',
    );
  }
  const cli = JSON.parse(readText(tree, cliPath));
  const apps = Object.entries<{ type?: string }>(cli.projects ?? {})
    .filter(([, p]) => p.type === 'application')
    .map(([name]) => name);
  return {
    root,
    apiSrc: `${prefix}apps/api/src`,
    apiModule: `${prefix}apps/api/src/api.module.ts`,
    apiMain: `${prefix}apps/api/src/main.ts`,
    commonSrc: `${prefix}libs/common/src`,
    databaseSrc: `${prefix}libs/database/src`,
    entitiesDir: `${prefix}libs/database/src/entities`,
    apps,
  };
}
